CREATE INDEX idx_webhook_log_actor ON public.webhook_log USING btree (actor_type, actor_id) WHERE (actor_id IS NOT NULL);
CREATE INDEX idx_webhook_log_trace_id ON public.webhook_log USING btree (trace_id) WHERE (trace_id IS NOT NULL);

