-- --- Views ---

CREATE VIEW "v_trace_timeline" AS
SELECT ae.trace_id,
    ae.ts,
    'activity'::text AS source,
    ae.actor_type,
    ae.actor_id,
    ae.action AS event,
    ae.target_type,
    ae.target_id,
    ae.result,
    ae.diff AS detail,
    ae.client_id,
    tc.client_name,
    tc.member_name,
    tc.member_email,
    tc.source_platform,
    tc.hardware_platform,
    tc.hardware_user_id,
    tc.plan_name,
    tc.door_name,
    tc.entry_point
   FROM (activity_event ae
     LEFT JOIN trace_context tc ON (((tc.trace_id)::text = (ae.trace_id)::text)))
  WHERE (ae.trace_id IS NOT NULL)
UNION ALL
 SELECT wl.trace_id,
    wl.received_at AS ts,
    'webhook'::text AS source,
    wl.actor_type,
    wl.actor_id,
    wl.event_type AS event,
    'webhook'::text AS target_type,
    wl.event_id AS target_id,
    wl.hmac_status AS result,
    wl.normalized_payload AS detail,
    wl.client_id,
    tc.client_name,
    tc.member_name,
    tc.member_email,
    tc.source_platform,
    tc.hardware_platform,
    tc.hardware_user_id,
    tc.plan_name,
    tc.door_name,
    tc.entry_point
   FROM (webhook_log wl
     LEFT JOIN trace_context tc ON (((tc.trace_id)::text = wl.trace_id)))
  WHERE (wl.trace_id IS NOT NULL)
UNION ALL
 SELECT dl.trace_id,
    dl.created_at AS ts,
    'diagnostic'::text AS source,
    dl.actor_type,
    dl.actor_id,
    dl.error_code AS event,
    dl.service AS target_type,
    NULL::character varying AS target_id,
    dl.level AS result,
    dl.context AS detail,
    dl.client_id,
    tc.client_name,
    tc.member_name,
    tc.member_email,
    tc.source_platform,
    tc.hardware_platform,
    tc.hardware_user_id,
    tc.plan_name,
    tc.door_name,
    tc.entry_point
   FROM (diagnostic_log dl
     LEFT JOIN trace_context tc ON (((tc.trace_id)::text = dl.trace_id)))
  WHERE (dl.trace_id IS NOT NULL)
UNION ALL
 SELECT mal.trace_id,
    mal.created_at AS ts,
    'member_access'::text AS source,
    mal.actor_type,
    mal.actor_id,
    mal.event_type AS event,
    'member'::text AS target_type,
    (mal.member_id)::text AS target_id,
    COALESCE(mal.error_code, 'success'::character varying) AS result,
    jsonb_build_object('mapping_id', mal.mapping_id, 'hardware_group_id', mal.hardware_group_id) AS detail,
    mal.client_id,
    tc.client_name,
    tc.member_name,
    tc.member_email,
    tc.source_platform,
    tc.hardware_platform,
    tc.hardware_user_id,
    tc.plan_name,
    tc.door_name,
    tc.entry_point
   FROM (member_access_log mal
     LEFT JOIN trace_context tc ON (((tc.trace_id)::text = (mal.trace_id)::text)))
  WHERE (mal.trace_id IS NOT NULL)
UNION ALL
 SELECT eq.trace_id,
    eq.created_at AS ts,
    'error_queue'::text AS source,
    eq.actor_type,
    eq.actor_id,
    eq.event_type AS event,
    'error'::text AS target_type,
    (eq.id)::text AS target_id,
    eq.status AS result,
    jsonb_build_object('error_reason', eq.error_reason, 'error_code', eq.error_code, 'plan_name', eq.plan_name, 'door_name', eq.door_name) AS detail,
    eq.client_id,
    tc.client_name,
    tc.member_name,
    tc.member_email,
    tc.source_platform,
    tc.hardware_platform,
    tc.hardware_user_id,
    tc.plan_name,
    tc.door_name,
    tc.entry_point
   FROM (error_queue eq
     LEFT JOIN trace_context tc ON (((tc.trace_id)::text = (eq.trace_id)::text)))
  WHERE (eq.trace_id IS NOT NULL)
UNION ALL
 SELECT aal.trace_id,
    COALESCE(aal.configured_at, aal.created_at) AS ts,
    'admin_audit'::text AS source,
    aal.actor_type,
    COALESCE(aal.actor_id, aal.configured_by) AS actor_id,
    COALESCE(aal.admin_action, aal.event_type) AS event,
    aal.target_entity AS target_type,
    (aal.target_id)::text AS target_id,
    aal.result,
    aal.details AS detail,
    aal.client_id,
    tc.client_name,
    tc.member_name,
    tc.member_email,
    tc.source_platform,
    tc.hardware_platform,
    tc.hardware_user_id,
    tc.plan_name,
    tc.door_name,
    tc.entry_point
   FROM (adapter_admin_log aal
     LEFT JOIN trace_context tc ON (((tc.trace_id)::text = (aal.trace_id)::text)))
  WHERE (aal.trace_id IS NOT NULL)
UNION ALL
 SELECT cal.trace_id,
    cal.created_at AS ts,
    'config_alert'::text AS source,
    cal.actor_type,
    cal.actor_id,
    cal.alert_type AS event,
    'config'::text AS target_type,
    (cal.plan_mapping_id)::text AS target_id,
        CASE
            WHEN (cal.resolved_at IS NULL) THEN 'open'::text
            ELSE 'resolved'::text
        END AS result,
    jsonb_build_object('hardware_ref', cal.hardware_ref, 'affected_member_count', cal.affected_member_count) AS detail,
    cal.client_id,
    tc.client_name,
    tc.member_name,
    tc.member_email,
    tc.source_platform,
    tc.hardware_platform,
    tc.hardware_user_id,
    tc.plan_name,
    tc.door_name,
    tc.entry_point
   FROM (config_alert_log cal
     LEFT JOIN trace_context tc ON (((tc.trace_id)::text = (cal.trace_id)::text)))
  WHERE (cal.trace_id IS NOT NULL)
  ORDER BY 2 DESC;
